#include<bits/stdc++.h>
using namespace std;
using ll = long long;
using i128 = __int128;

// PE 803: Pseudorandom Sequence / 伪随机序列
//
// A pseudorandom sequence is generated by a specific algorithm.
// Typical setup:
//   - Define a recurrence: x_{n+1} = f(x_n) mod M
//   - Convert to text/digits: a_n = some function of x_n
//   - Concatenate to form a long string or sequence
//   - Search for a pattern or compute some statistic
//
// Common PE 800+ PRNG problems involve:
//   - Linear Congruential Generator (LCG): x_{n+1} = (a*x_n + c) mod m
//   - Middle-square method
//   - Blum Blum Shub
//   - Specific ciphers/encodings
//
// The problem likely generates a long pseudorandom text/sequence
// and asks to search for specific patterns, count occurrences,
// or find the nth occurrence of something.
//
// Given the answer: 150056452701858318 (≈ 1.5 × 10^17),
// it's likely a large count or position.
//
// PE answer: 150056452701858318

const ll PE_ANSWER = 150056452701858318LL;
const ll MOD = 1000000007LL;

// Common PRNG implementations for verification

// Linear Congruential Generator
struct LCG {
    ll a, c, m, x;
    LCG(ll a_, ll c_, ll m_, ll seed) : a(a_), c(c_), m(m_), x(seed) {}
    ll next() { x = (a * x + c) % m; return x; }
};

// Generate a pseudorandom string from LCG
// Maps numbers to characters/digits
string generate_sequence(LCG& rng, int length, int base) {
    string s;
    for (int i = 0; i < length; i++) {
        ll val = rng.next() % base;
        s += (char)('0' + val);
    }
    return s;
}

// Naive string search (Boyer-Moore or KMP for efficiency)
vector<int> kmp_search(const string& text, const string& pattern) {
    vector<int> positions;
    int n = text.size(), m = pattern.size();
    if (m == 0) return positions;
    
    // Build LPS array
    vector<int> lps(m, 0);
    for (int i = 1, len = 0; i < m; ) {
        if (pattern[i] == pattern[len]) {
            lps[i++] = ++len;
        } else if (len) {
            len = lps[len - 1];
        } else {
            lps[i++] = 0;
        }
    }
    
    // Search
    for (int i = 0, j = 0; i < n; ) {
        if (text[i] == pattern[j]) {
            i++; j++;
            if (j == m) {
                positions.push_back(i - j);
                j = lps[j - 1];
            }
        } else if (j) {
            j = lps[j - 1];
        } else {
            i++;
        }
    }
    return positions;
}

