    cout << "3. Xorshift: x ^= x<<a; x ^= x>>b; x ^= x<<c\n";
    cout << "4. Blum Blum Shub: x_{n+1} = x_n^2 mod M\n";
    cout << "5. Mersenne Twister (MT19937)\n\n";
    
    cout << "=== LCG Demo ===\n";
    LCG rng(1103515245, 12345, 1LL << 31, 1);
